export function PricingPage(){
  const { user }=useAuth(); const [rules,setRules]=useState([]); const [loading,setLoading]=useState(true); const [error,setError]=useState(''); const [creating,setCreating]=useState(false); const [previewing,setPreviewing]=useState(false); const [preview,setPreview]=useState(null)
  useEffect(()=>{loadEndpoint('/pricing/',user.role).then(r=>{setRules(r.data.items);setLoading(false)}).catch(e=>{setError(e.message);setLoading(false)})},[user.role])
  async function add(form){const r=await createEndpoint('/pricing/',form,user.role);setRules(c=>[...c,r.item])}
  async function calculate(form){const r=await createEndpoint('/pricing/',{...form,action:'preview'},user.role);setPreview(r.item)}
  return <><OpsHeader eyebrow="Commercial engine" title="Pricing & discount rules" copy="Separate retail, dealer and wholesale pricing, then apply quantity rules without calculator gymnastics." action={<div className="inline-actions"><button className="button ghost app-action" onClick={()=>setPreviewing(true)}>Price calculator</button><button className="button app-action" onClick={()=>setCreating(true)}>+ Rule</button></div>}/>{preview&&<article className="pricing-preview"><div><span className="eyebrow">Calculated offer</span><h2>{preview.name}</h2><p>{preview.sku} · {preview.customer_type} · {preview.quantity} units</p></div><div><small>Unit price</small><strong>₹{Number(preview.unit_price).toLocaleString('en-IN')}</strong><span>{preview.discount_percent}% rule discount</span></div><div><small>Line total</small><strong>₹{Number(preview.line_total).toLocaleString('en-IN')}</strong><span>{preview.margin_percent!==null?`${preview.margin_percent}% estimated margin`:'Margin n/a'}</span></div></article>}{loading?<Loading/>:error?<ErrorBox message={error}/>:<div className="table-card"><table><thead><tr><th>Rule</th><th>Customer type</th><th>Minimum qty</th><th>Discount</th><th>Status</th></tr></thead><tbody>{rules.map(r=><tr key={r.id}><td><b>{r.name}</b></td><td className="capitalize">{r.customer_type}</td><td>{r.min_qty}</td><td>{r.discount_percent}%</td><td>{r.active?'Active':'Paused'}</td></tr>)}</tbody></table></div>}{creating&&<CreateModal title="Add price rule" copy="Apply a quantity discount to a customer segment." submitLabel="Add rule" onClose={()=>setCreating(false)} onSubmit={add} initial={{customer_type:'dealer',min_qty:1,discount_percent:0}} fields={[{name:'name',label:'Rule name',required:true,span:2},{name:'customer_type',label:'Customer type',type:'select',options:['retail','dealer','fleet','workshop']},{name:'min_qty',label:'Minimum quantity',type:'number',min:'1'},{name:'discount_percent',label:'Discount %',type:'number',min:'0',step:'0.1'}]}/>} {previewing&&<CreateModal title="Price calculator" copy="Preview the price that a customer segment receives at a given quantity." submitLabel="Calculate" onClose={()=>setPreviewing(false)} onSubmit={calculate} initial={{customer_type:'dealer',quantity:1}} fields={[{name:'sku',label:'SKU',required:true},{name:'customer_type',label:'Customer type',type:'select',options:['retail','dealer','fleet','workshop']},{name:'quantity',label:'Quantity',type:'number',min:'1',required:true}]}/>}</>
}

function currency(v){return new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(v||0)}
function Bars({items}){const max=Math.max(1,...items.map(x=>Number(x.value)||0));return <div className="bar-list">{items.map(x=><div className="bar-row" key={x.label}><div><b>{x.label}</b><span>{Number(x.value).toLocaleString('en-IN')}</span></div><i><em style={{width:`${Math.max(4,(Number(x.value)||0)/max*100)}%`}}></em></i></div>)}</div>}
export function AnalyticsPage(){
  const { user }=useAuth(); const [data,setData]=useState(null); const [loading,setLoading]=useState(true); const [error,setError]=useState('')
  useEffect(()=>{loadEndpoint('/analytics/',user.role).then(r=>{setData(r.data);setLoading(false)}).catch(e=>{setError(e.message);setLoading(false)})},[user.role])
  function exportCsv(){if(!data)return;const rows=[['Metric','Value'],...Object.entries(data.metrics)];const blob=new Blob([rows.map(r=>r.join(',')).join('\n')],{type:'text/csv'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='partora-analytics.csv';a.click();URL.revokeObjectURL(a.href)}
  return <><OpsHeader eyebrow="Intelligence" title="Analytics & business reports" copy="Track commercial performance, inventory value, conversion and working-capital exposure." action={<button className="button app-action" onClick={exportCsv}>Export CSV</button>}/>{loading?<Loading/>:error?<ErrorBox message={error}/>:<><section className="metric-grid dashboard-metrics"><article><small>Sales orders</small><strong>{currency(data.metrics.sales_total)}</strong><span>confirmed value</span></article><article><small>Inventory value</small><strong>{currency(data.metrics.inventory_value)}</strong><span>{data.metrics.low_stock} low-stock SKUs</span></article><article><small>Outstanding</small><strong>{currency(data.metrics.outstanding)}</strong><span>customer balance</span></article><article><small>Quote conversion</small><strong>{data.metrics.quote_conversion}%</strong><span>approved quotes</span></article></section><section className="analytics-grid"><article className="data-card"><div className="card-title"><div><span className="eyebrow">Mix</span><h2>Catalog categories</h2></div></div><Bars items={data.categories}/></article><article className="data-card"><div className="card-title"><div><span className="eyebrow">Sourcing</span><h2>Supplier SKU coverage</h2></div></div><Bars items={data.suppliers}/></article><article className="data-card"><div className="card-title"><div><span className="eyebrow">Credit</span><h2>Customer exposure</h2></div></div><Bars items={data.top_customers}/></article><article className="data-card insight-card"><span className="eyebrow">Estimated inventory margin</span><strong>{currency(data.metrics.estimated_inventory_margin)}</strong><p>Difference between current catalog selling value and stored product cost across on-hand inventory.</p></article></section></>}</>
}

